const ExcelJS = require('exceljs');
const config = require('./config');
const coreDb = require('./db/core');
const { getTenantDbByName } = require('./db/tenantConnections');
const { sendEmail } = require('./utils/email');

/**
 * Monthly Sitara Razorpay-vs-BigCommerce sales reconciliation — a single
 * chronological list of every CAPTURED Razorpay payment for the period
 * (matched to its BigCommerce/sitara_orders row where possible, left blank
 * with an explanatory note where not), explicitly requested 2026-11-02 in
 * the exact format of a report generated by hand for September — validated
 * directly against that original report before this was built (date/time/
 * status-label formatting fixed to match; the handful of remaining
 * differences were confirmed to be real data drift — order statuses
 * progressing and a few since-unlinked "Incomplete" orders — not a logic
 * bug).
 *
 * Deliberately reuses sitara_razorpay_payments.order_id (the SAME link the
 * live "Razorpay" section and the daily backfill/webhook sync already
 * maintain) rather than re-deriving a match independently — unlike
 * sitaraWeeklyReconciliation.js (which re-derives via Razorpay's own
 * notes.bigc_order_id specifically to catch sync gaps), this report's whole
 * point is to mirror what the system already believes is matched, in one
 * plain chronological list a non-technical reader can scan top to bottom.
 */

let pollTimer = null;
let running = false;

const MONTH_ABBR = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

// snake_case (this table's own enum — see BC_STATUS_MAP in src/routes/
// sitara.js) -> the Title Case label BigCommerce itself uses, for display.
const STATUS_LABELS = {
  incomplete: 'Incomplete', pending: 'Pending', awaiting_payment: 'Awaiting Payment',
  awaiting_fulfillment: 'Awaiting Fulfillment', awaiting_shipment: 'Awaiting Shipment',
  awaiting_pickup: 'Awaiting Pickup', partially_shipped: 'Partially Shipped', shipped: 'Shipped',
  completed: 'Completed', cancelled: 'Cancelled', declined: 'Declined', refunded: 'Refunded',
  partially_refunded: 'Partially Refunded', disputed: 'Disputed',
  manual_verification_required: 'Manual Verification Required', verified: 'Verified',
};
function statusLabel(status) { return STATUS_LABELS[status] || status || ''; }

function istParts(date) {
  const fmt = new Intl.DateTimeFormat('en-US', {
    timeZone: 'Asia/Kolkata', day: '2-digit', month: 'numeric', year: 'numeric',
    hour: '2-digit', minute: '2-digit', hour12: true,
  });
  const parts = Object.fromEntries(fmt.formatToParts(date).map((p) => [p.type, p.value]));
  const dateStr = `${parts.day}-${MONTH_ABBR[Number(parts.month) - 1]}-${parts.year}`;
  let hour = parts.hour;
  if (hour.length < 2) hour = '0' + hour;
  const timeStr = `${hour}:${parts.minute} ${parts.dayPeriod.toUpperCase()}`;
  return { dateStr, timeStr };
}

// `fromIso`/`toIso` are plain 'YYYY-MM-DD' calendar dates, IST-local — offset
// by +05:30 so the comparison against captured_at (stored as the raw UTC
// instant) lines up with the intended IST day boundaries, same reasoning as
// sitaraWeeklyReconciliation.js's own from/to window.
function istDateBoundaryToUtc(isoDateStr, endOfDay) {
  return new Date(isoDateStr + (endOfDay ? 'T23:59:59.999' : 'T00:00:00.000') + '+05:30');
}

async function fetchReportRows({ fromIso, toIso }) {
  const company = await coreDb('companies').where({ slug: 'sitara' }).first();
  if (!company) return null;
  const db = getTenantDbByName(company.db_name);

  const from = istDateBoundaryToUtc(fromIso, false);
  const to = istDateBoundaryToUtc(toIso, true);

  const payments = await db('sitara_razorpay_payments')
    .leftJoin('sitara_orders', 'sitara_razorpay_payments.order_id', 'sitara_orders.id')
    .leftJoin('sitara_customers', 'sitara_orders.customer_id', 'sitara_customers.id')
    .where('sitara_razorpay_payments.status', 'captured')
    .andWhere('sitara_razorpay_payments.captured_at', '>=', from)
    .andWhere('sitara_razorpay_payments.captured_at', '<=', to)
    .select(
      'sitara_razorpay_payments.razorpay_payment_id as razorpayPaymentId',
      'sitara_razorpay_payments.amount as amount',
      'sitara_razorpay_payments.captured_at as capturedAt',
      'sitara_razorpay_payments.order_id as orderId',
      'sitara_orders.order_number as orderNumber',
      'sitara_orders.status as orderStatus',
      'sitara_customers.name as customerName',
      'sitara_customers.email as customerEmail',
      'sitara_customers.phone as customerPhone',
      'sitara_customers.address_line1 as customerAddressLine1',
      'sitara_customers.address_line2 as customerAddressLine2',
      'sitara_customers.state as customerState'
    )
    .orderBy('sitara_razorpay_payments.captured_at', 'asc');

  const orderIds = [...new Set(payments.filter((p) => p.orderId).map((p) => p.orderId))];
  const items = orderIds.length
    ? await db('sitara_order_items').whereIn('order_id', orderIds).select('order_id', 'product_name', 'quantity')
    : [];
  const itemsByOrder = new Map();
  for (const it of items) {
    if (!itemsByOrder.has(it.order_id)) itemsByOrder.set(it.order_id, []);
    itemsByOrder.get(it.order_id).push(`${it.product_name} x${it.quantity}`);
  }

  const rows = payments.map((p) => {
    const { dateStr, timeStr } = istParts(new Date(p.capturedAt));
    const matched = !!p.orderId;
    return {
      date: dateStr, time: timeStr,
      customerName: matched ? (p.customerName || '') : '',
      customerEmail: matched ? (p.customerEmail || '') : '',
      customerPhone: matched ? (p.customerPhone || '') : '',
      customerAddress: matched ? [p.customerAddressLine1, p.customerAddressLine2].filter(Boolean).join(', ') : '',
      customerState: matched ? (p.customerState || '') : '',
      orderNumber: matched ? (p.orderNumber || '') : '',
      items: matched ? (itemsByOrder.get(p.orderId) || []).join('; ') : '',
      amount: Number(p.amount),
      razorpayPaymentId: p.razorpayPaymentId,
      orderStatus: matched ? statusLabel(p.orderStatus) : '',
      note: matched ? '' : 'Payment not matched to any order: customer & items unavailable',
    };
  });

  const total = rows.reduce((s, r) => s + r.amount, 0);
  return { rows, total, matchedCount: rows.filter((r) => !r.note).length, unmatchedCount: rows.filter((r) => r.note).length };
}

async function buildWorkbookBuffer({ rows, total, fromLabel, toLabel }) {
  const workbook = new ExcelJS.Workbook();
  const sheet = workbook.addWorksheet(`${fromLabel} to ${toLabel}`);
  sheet.columns = [
    { header: 'S.No', key: 'sno', width: 6 },
    { header: 'Date (IST)', key: 'date', width: 14 },
    { header: 'Time (IST)', key: 'time', width: 12 },
    { header: 'Customer Name', key: 'customerName', width: 24 },
    { header: 'Customer Email', key: 'customerEmail', width: 28 },
    { header: 'Customer Phone', key: 'customerPhone', width: 16 },
    { header: 'Customer Address', key: 'customerAddress', width: 34 },
    { header: 'State', key: 'customerState', width: 16 },
    { header: 'Order Number', key: 'orderNumber', width: 14 },
    { header: 'Items Ordered', key: 'items', width: 40 },
    { header: 'Amount (INR)', key: 'amount', width: 16 },
    { header: 'Razorpay Payment ID', key: 'razorpayPaymentId', width: 22 },
    { header: 'Order Status', key: 'orderStatus', width: 20 },
    { header: 'Note', key: 'note', width: 55 },
  ];
  sheet.getRow(1).font = { bold: true };
  sheet.getRow(1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFDCE6F1' } };
  rows.forEach((r, i) => {
    sheet.addRow({
      sno: i + 1, date: r.date, time: r.time, customerName: r.customerName, customerEmail: r.customerEmail,
      customerPhone: r.customerPhone, customerAddress: r.customerAddress, customerState: r.customerState,
      orderNumber: r.orderNumber, items: r.items, amount: r.amount,
      razorpayPaymentId: r.razorpayPaymentId, orderStatus: r.orderStatus, note: r.note,
    });
  });
  sheet.getColumn('amount').numFmt = '₹#,##0.00';
  const totalRow = sheet.addRow({});
  const labelRow = sheet.addRow({ items: 'Total', amount: total });
  labelRow.getCell('items').font = { bold: true };
  labelRow.getCell('amount').font = { bold: true };
  labelRow.getCell('amount').numFmt = '₹#,##0.00';
  sheet.autoFilter = { from: 'A1', to: 'N1' };
  return workbook.xlsx.writeBuffer();
}

async function runMonthlyReport({ fromIso, toIso, fromLabel, toLabel }) {
  const result = await fetchReportRows({ fromIso, toIso });
  if (!result) { console.log('[sitara-monthly-reconciliation] Sitara company not provisioned — skipping.'); return null; }
  const { rows, total, matchedCount, unmatchedCount } = result;
  const buffer = await buildWorkbookBuffer({ rows, total, fromLabel, toLabel });
  const filename = `Sitara_Drapes_Razorpay_Sales_${fromLabel}_to_${toLabel}.xlsx`;

  const html = `
    <p>Sitara Drapes — Razorpay captured payments matched against BigCommerce orders, <strong>${fromLabel} to ${toLabel}</strong>.</p>
    <ul>
      <li>Captured payments matched to a real order: <strong>${matchedCount}</strong></li>
      <li>Captured payments with no matching order: <strong>${unmatchedCount}</strong></li>
      <li>Total captured: <strong>₹${total.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</strong></li>
    </ul>
    <p>Full detail attached.</p>
  `;

  await sendEmail({
    to: config.sitaraMonthlyReconciliation.recipientTo,
    cc: config.sitaraMonthlyReconciliation.recipientCc,
    subject: `Sitara Drapes Razorpay Sales — ${fromLabel} to ${toLabel}`,
    html,
    text: html.replace(/<[^>]+>/g, ''),
    attachments: [{ name: filename, contentType: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', contentInBase64: buffer.toString('base64') }],
  });

  console.log(`[sitara-monthly-reconciliation] sent report ${fromLabel}-${toLabel}: ${matchedCount} matched, ${unmatchedCount} unmatched, total ₹${total.toFixed(2)}.`);
  return { rows, total, matchedCount, unmatchedCount, buffer, filename };
}

/** Full previous calendar month, in IST — e.g. run on/after Nov 1st produces Oct 1-31. */
function previousMonthRange() {
  const nowIst = new Date(new Date().toLocaleString('en-US', { timeZone: 'Asia/Kolkata' }));
  const year = nowIst.getFullYear();
  const month = nowIst.getMonth(); // 0-based; the PREVIOUS month is month-1
  const prevMonthDate = new Date(year, month - 1, 1);
  const prevYear = prevMonthDate.getFullYear();
  const prevMonth = prevMonthDate.getMonth(); // 0-based
  const lastDay = new Date(prevYear, prevMonth + 1, 0).getDate();
  const pad = (n) => String(n).padStart(2, '0');
  const fromIso = `${prevYear}-${pad(prevMonth + 1)}-01`;
  const toIso = `${prevYear}-${pad(prevMonth + 1)}-${pad(lastDay)}`;
  const monthKey = `${prevYear}-${pad(prevMonth + 1)}`;
  const label = `${MONTH_ABBR[prevMonth]} ${prevYear}`;
  return { fromIso, toIso, monthKey, fromLabel: label, toLabel: label };
}

async function checkAndRun() {
  if (running || !config.email.enabled || !config.razorpay.enabled) return;
  running = true;
  try {
    const { fromIso, toIso, monthKey, fromLabel, toLabel } = previousMonthRange();
    const state = await coreDb('ai_sitara_monthly_reconciliation_state').where({ id: 'sitara' }).first();
    if (state?.last_sent_month === monthKey) return; // already sent for this month

    await runMonthlyReport({ fromIso, toIso, fromLabel, toLabel });

    if (state) await coreDb('ai_sitara_monthly_reconciliation_state').where({ id: 'sitara' }).update({ last_sent_month: monthKey, last_run_at: new Date(), updated_at: new Date() });
    else await coreDb('ai_sitara_monthly_reconciliation_state').insert({ id: 'sitara', last_sent_month: monthKey, last_run_at: new Date(), updated_at: new Date() });
  } catch (e) {
    console.error('[sitara-monthly-reconciliation] run failed:', e.message);
  } finally {
    running = false;
  }
}

/** Call once from server.js. No-op if email or Razorpay isn't configured. */
function start() {
  if (!config.email.enabled || !config.razorpay.enabled) {
    console.log('[sitara-monthly-reconciliation] Email or Razorpay not configured — scheduler not started.');
    return;
  }
  if (pollTimer) return;
  checkAndRun().catch((e) => console.error('[sitara-monthly-reconciliation] initial check failed:', e.message));
  pollTimer = setInterval(checkAndRun, config.sitaraMonthlyReconciliation.checkIntervalMs);
  pollTimer.unref?.();
}

module.exports = { start, runMonthlyReport, fetchReportRows, previousMonthRange };
